import type { RowDataPacket } from "mysql2/promise"
import { Clock, Effect } from "effect"

import { Database } from "@/effect/database"
import { DomainConfigurationError } from "@/effect/errors"
import { databaseTable } from "@/lib/database-config"

export type WebHostnameResourceType = "app" | "instance"

/**
 * A web hostname whose DNS record Kiln keeps in Cloudflare, pointing at the
 * Relay its game server or app runs on.
 */
export interface WebHostname {
  /** The connection whose token manages its zone. */
  connectionId: string
  createdAt: number
  /** Generated by Kiln as an app's address, kept without a route. */
  generated: boolean
  hostname: string
  id: string
  lastError: string | null
  recordId: string | null
  recordType: "A" | "AAAA" | "CNAME" | null
  relayId: string
  resourceId: string
  resourceType: WebHostnameResourceType
  /**
   * `external` when Cloudflare already had a record Kiln didn't make; Kiln
   * leaves it alone and checks again on the next sync.
   */
  status: "active" | "error" | "external" | "pending" | "removing"
  /** What the record points at: the Relay's public address. */
  target: string | null
  /** The vanity domain it's named under, when it is. */
  vanityDomain: string | null
  zoneId: string
}

export interface WebHostnameResource {
  readonly relayId: string
  readonly resourceId: string
  readonly resourceType: WebHostnameResourceType
}

interface WebHostnameRow extends RowDataPacket {
  created_at: number
  hostname: string
  id: string
  integration_id: string
  is_generated: boolean | number
  last_error: string | null
  record_id: string | null
  record_type: "A" | "AAAA" | "CNAME" | null
  relay_id: string
  resource_id: string
  resource_type: WebHostnameResourceType
  status: WebHostname["status"]
  target: string | null
  vanity_domain: string | null
  zone_id: string
}

const webHostnameSelect = `SELECT id, hostname, relay_id, resource_type,
       resource_id, integration_id, zone_id, vanity_domain, is_generated,
       record_id, record_type, target, status, last_error, created_at
  FROM ${databaseTable("web_hostname")}`

export const loadWebHostnameEffect = Effect.fn("webHostnames.load")(function* (
  id: string
) {
  const database = yield* Database
  const rows = yield* database.queryRows<WebHostnameRow>(
    "webHostnames.load",
    `${webHostnameSelect} WHERE id = ? LIMIT 1`,
    [id]
  )
  const row = rows[0]
  return row ? webHostname(row) : null
})

export const loadWebHostnameByNameEffect = Effect.fn("webHostnames.byName")(
  function* (hostname: string) {
    const database = yield* Database
    const rows = yield* database.queryRows<WebHostnameRow>(
      "webHostnames.byName",
      `${webHostnameSelect} WHERE hostname = ? LIMIT 1`,
      [hostname]
    )
    const row = rows[0]
    return row ? webHostname(row) : null
  }
)

/** A game server's or app's hostnames, generated first, then by name. */
export const listResourceWebHostnamesEffect = Effect.fn(
  "webHostnames.resource"
)(function* (resource: WebHostnameResource) {
  const database = yield* Database
  const rows = yield* database.queryRows<WebHostnameRow>(
    "webHostnames.resource",
    `${webHostnameSelect}
      WHERE relay_id = ? AND resource_type = ? AND resource_id = ?
      ORDER BY is_generated DESC, hostname`,
    [resource.relayId, resource.resourceType, resource.resourceId]
  )
  return rows.map(webHostname)
})

/** Every hostname, or one Relay's or one connection's. */
export const listWebHostnamesEffect = Effect.fn("webHostnames.list")(
  function* (filter?: { connectionId?: string; relayId?: string }) {
    const database = yield* Database
    const conditions: Array<string> = []
    const values: Array<string> = []
    if (filter?.relayId) {
      conditions.push("relay_id = ?")
      values.push(filter.relayId)
    }
    if (filter?.connectionId) {
      conditions.push("integration_id = ?")
      values.push(filter.connectionId)
    }
    const rows = yield* database.queryRows<WebHostnameRow>(
      "webHostnames.list",
      `${webHostnameSelect}
        ${conditions.length > 0 ? `WHERE ${conditions.join(" AND ")}` : ""}
        ORDER BY hostname`,
      values
    )
    return rows.map(webHostname)
  }
)

/**
 * The game server or app holding a hostname: by a web hostname Kiln keeps,
 * or a game server's vanity address. Null when neither does.
 */
export const loadHostnameHolderEffect = Effect.fn("webHostnames.holder")(
  function* (hostname: string) {
    const database = yield* Database
    const [row] = yield* database.queryRows<
      RowDataPacket & {
        relay_id: string
        resource_id: string
        resource_type: WebHostnameResourceType
      }
    >(
      "webHostnames.holder",
      `SELECT resource_type, relay_id, resource_id
         FROM ${databaseTable("web_hostname")}
        WHERE hostname = ?
       UNION ALL
       SELECT 'instance', relay_id, instance_id
         FROM ${databaseTable("instance_domain")}
        WHERE CONCAT(vanity_label, '.', domain) = ?
       LIMIT 1`,
      [hostname, hostname]
    )
    return row
      ? {
          relayId: row.relay_id,
          resourceId: row.resource_id,
          resourceType: row.resource_type,
        }
      : null
  }
)

/**
 * Holds a hostname for a resource before its record exists. A hostname
 * another resource holds fails rather than being taken over.
 */
export const insertWebHostnameEffect = Effect.fn("webHostnames.insert")(
  function* (
    input: WebHostnameResource & {
      connectionId: string
      generated: boolean
      hostname: string
      id: string
      vanityDomain: string | null
      zoneId: string
    }
  ) {
    const database = yield* Database
    const now = yield* Clock.currentTimeMillis
    const result = yield* database.execute(
      "webHostnames.insert",
      // Nor one a game server's address has; that insert checks this
      // table the same way.
      `INSERT IGNORE INTO ${databaseTable("web_hostname")}
         (id, hostname, relay_id, resource_type, resource_id, integration_id,
          zone_id, vanity_domain, is_generated, status, created_at, updated_at)
       SELECT ?, ?, ?, ?, ?, ?, ?, ?, ?, 'pending', ?, ?
         FROM DUAL
        WHERE NOT EXISTS (
          SELECT 1 FROM ${databaseTable("instance_domain")}
           WHERE CONCAT(vanity_label, '.', domain) = ?)`,
      [
        input.id,
        input.hostname,
        input.relayId,
        input.resourceType,
        input.resourceId,
        input.connectionId,
        input.zoneId,
        input.vanityDomain,
        input.generated,
        now,
        now,
        input.hostname,
      ]
    )
    if (result.affectedRows === 0) {
      return yield* DomainConfigurationError.make({
        message: `${input.hostname} is already in use`,
      })
    }
  }
)

/**
 * Records the DNS record Kiln made or updated for a hostname. False when the
 * hostname was let go meanwhile, so the caller deletes the record it made.
 */
export const activateWebHostnameEffect = Effect.fn("webHostnames.activate")(
  function* (input: {
    id: string
    recordId: string
    recordType: "A" | "AAAA" | "CNAME"
    target: string
  }) {
    const database = yield* Database
    const now = yield* Clock.currentTimeMillis
    const result = yield* database.execute(
      "webHostnames.activate",
      `UPDATE ${databaseTable("web_hostname")}
          SET record_id = ?, record_type = ?, target = ?, status = 'active',
              last_error = NULL, updated_at = ?
        WHERE id = ?`,
      [input.recordId, input.recordType, input.target, now, input.id]
    )
    return result.affectedRows > 0
  }
)

export const setWebHostnameStatusEffect = Effect.fn("webHostnames.setStatus")(
  function* (
    id: string,
    status: "error" | "external" | "pending" | "removing",
    message: string | null
  ) {
    const database = yield* Database
    const now = yield* Clock.currentTimeMillis
    yield* database.execute(
      "webHostnames.setStatus",
      `UPDATE ${databaseTable("web_hostname")}
          SET status = ?, last_error = ?, updated_at = ?
        WHERE id = ?`,
      [status, message?.slice(0, 512) ?? null, now, id]
    )
  }
)

/** Forgets a record Kiln deleted or found gone, so a sync makes it again. */
export const clearWebHostnameRecordEffect = Effect.fn(
  "webHostnames.clearRecord"
)(function* (id: string) {
  const database = yield* Database
  const now = yield* Clock.currentTimeMillis
  yield* database.execute(
    "webHostnames.clearRecord",
    `UPDATE ${databaseTable("web_hostname")}
        SET record_id = NULL, record_type = NULL, target = NULL,
            updated_at = ?
      WHERE id = ?`,
    [now, id]
  )
})

export const deleteWebHostnameEffect = Effect.fn("webHostnames.delete")(
  function* (id: string) {
    const database = yield* Database
    yield* database.execute(
      "webHostnames.delete",
      `DELETE FROM ${databaseTable("web_hostname")} WHERE id = ?`,
      [id]
    )
  }
)

/**
 * Gives a resource's hostnames to the one taking its place, as moving a game
 * server to another Relay does. Ones being deleted stay with their delete.
 * Reports how many moved.
 */
export const reassignWebHostnamesEffect = Effect.fn("webHostnames.reassign")(
  function* (from: WebHostnameResource, to: WebHostnameResource) {
    const database = yield* Database
    const now = yield* Clock.currentTimeMillis
    const result = yield* database.execute(
      "webHostnames.reassign",
      `UPDATE ${databaseTable("web_hostname")}
          SET relay_id = ?, resource_type = ?, resource_id = ?, updated_at = ?
        WHERE relay_id = ? AND resource_type = ? AND resource_id = ?
          AND status <> 'removing'`,
      [
        to.relayId,
        to.resourceType,
        to.resourceId,
        now,
        from.relayId,
        from.resourceType,
        from.resourceId,
      ]
    )
    return result.affectedRows
  }
)

function webHostname(row: WebHostnameRow): WebHostname {
  return {
    connectionId: row.integration_id,
    createdAt: Number(row.created_at),
    generated: Boolean(row.is_generated),
    hostname: row.hostname,
    id: row.id,
    lastError: row.last_error,
    recordId: row.record_id,
    recordType: row.record_type,
    relayId: row.relay_id,
    resourceId: row.resource_id,
    resourceType: row.resource_type,
    status: row.status,
    target: row.target,
    vanityDomain: row.vanity_domain,
    zoneId: row.zone_id,
  }
}
